function sbHistAvg(owner,key,before){const tids=sbTids(owner);let s=0,n=0;for(const tid of tids){const h=SB.hist[tid];if(!h||!h[key]||h[key].length<3)return null;s+=sbAvg(h[key]);n++}return n?s/n:null}
