function sbParlayOpen(){if(typeof RQ==='undefined'||!RQ||typeof RQ.parlayBegin!=='function')return;const me=sbMe(),now=Date.now(),mine=new Set(me?sbTids(me):[]),rows=[];for(const g of D.games||[]){if(!g||!g.start||!g.away||!g.home||g.status==='final'||!(Date.parse(g.start)>now)||!g.line||!(+g.line.sp>0))continue;rows.push({g,owned:mine.has(String(g.away.id))||mine.has(String(g.home.id))})}rows.sort((a,b)=>(b.owned-a.owned)||String(a.g.start).localeCompare(String(b.g.start)));const g=rows[0]&&rows[0].g;if(g&&typeof RQ.prefill==='function')RQ.prefill(String(g.id),null,0);RQ.parlayBegin(g?String(g.id):'');if(typeof obView==='function')obView('request')}
